<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {settlementAmount} from '../supplemental'
import type {SupplementalPayslip} from '../supplemental'
const props=defineProps<{year:string}>(),{api,english,base,current,store,message}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z,money=(v:string|null|undefined)=>settlementAmount(v,english()),rows=ref<SupplementalPayslip[]>([]),selected=ref<SupplementalPayslip|null>(null),loading=ref(false),failure=ref('')
let revision=0
const visible=computed(()=>rows.value.filter(p=>p.settlementMonth.startsWith(props.year+'-')))
async function refresh(){const rev=++revision,captured=store.value;selected.value=null;rows.value=[];loading.value=true;failure.value='';try{const v=await api().get<SupplementalPayslip[]>('/my-supplemental-payslips');if(current()&&rev===revision&&captured===store.value)rows.value=v}catch(e){if(current()&&rev===revision)failure.value=message(e)}finally{if(rev===revision)loading.value=false}}
async function open(id:string){const rev=++revision,captured=store.value;selected.value=null;loading.value=true;failure.value='';try{const v=await api().get<SupplementalPayslip>('/my-supplemental-payslips/'+encodeURIComponent(id));if(current()&&rev===revision&&captured===store.value&&v.batchId===id)selected.value=v}catch(e){if(current()&&rev===revision)failure.value=message(e)}finally{if(rev===revision)loading.value=false}}
watch(()=>props.year,()=>{if(/^\d{4}$/.test(props.year))void refresh();else{revision++;selected.value=null;rows.value=[];loading.value=false}})
onMounted(()=>void refresh())
</script>
<template><section class="wf-section"><header class="wf-toolbar"><h3>{{x('我的补发工资单','My supplemental payslips')}}</h3><button :disabled="loading" @click="refresh">{{x('刷新本人补发工资单','Refresh my supplemental payslips')}}</button></header><p>{{x('按补发结算年度筛选；原贡献月份单独列示。','Filtered by supplemental settlement year; original contribution months remain separate.')}}</p><p v-if="loading" role="status">{{x('正在读取本人补发工资单…','Loading your supplemental payslips…')}}</p><p v-if="failure" role="alert">{{failure}}</p><div v-if="!loading" class="wf-table-wrap"><table><thead><tr><th>{{x('公司','Company')}}</th><th>{{x('原贡献月／结算月','Original / settlement month')}}</th><th>{{x('新增收入／现金应付','New gross / cash payable')}}</th><th>{{x('已付／剩余','Paid / remaining')}}</th><th></th></tr></thead><tbody><tr v-for="p in visible" :key="p.batchId"><td>{{p.companyName}}</td><td>{{p.originMonth}} / {{p.settlementMonth}}</td><td>{{money(p.grossDelta)}} / {{money(p.employeeCashPayable)}}</td><td>{{money(p.paidAmount)}} / {{money(p.remainingAmount)}}</td><td><button @click="open(p.batchId)">{{x('查看补发工资单','View supplemental payslip')}}</button></td></tr><tr v-if="!visible.length"><td colspan="5">{{x('本年度暂无已发布补发工资单。','No published supplemental payslips for this year.')}}</td></tr></tbody></table></div><article v-if="selected" class="wf-section"><h4>{{selected.companyName}} · {{selected.employeeName}}</h4><p>{{x('原贡献月／结算月','Original / settlement month')}}: {{selected.originMonth}} / {{selected.settlementMonth}}</p><dl class="wf-details"><dt>{{x('新增收入','New gross')}}</dt><dd>{{money(selected.grossDelta)}}</dd><dt>{{x('本次员工CPF／CDAC扣款','Employee CPF / CDAC deduction')}}</dt><dd>{{money(selected.employeeCpfDeduction)}} / {{money(selected.cdacDeduction)}}</dd><dt>{{x('员工现金应付／已付／剩余','Cash payable / paid / remaining')}}</dt><dd>{{money(selected.employeeCashPayable)}} / {{money(selected.paidAmount)}} / {{money(selected.remainingAmount)}}</dd></dl><div class="wf-table-wrap"><table><thead><tr><th>{{x('项目','Item')}}</th><th>{{x('业务类别／OW或AW','Business category / OW or AW')}}</th><th>{{x('金额','Amount')}}</th><th>{{x('原贡献月／结算月','Original / settlement month')}}</th></tr></thead><tbody><tr v-for="(i,index) in selected.items||[]" :key="index"><td>{{i.label}}</td><td>{{i.businessType==='leave_encashment'?x('未休年假折现','Unused annual leave encashment'):i.businessType==='bonus'?x('奖金','Bonus'):i.businessType==='aws'?'AWS':i.businessType==='retroactive_increment'?x('追溯加薪','Retroactive increment'):i.businessType==='omitted_wages'?x('原已到期遗漏工资','Originally due omitted wages'):i.businessType}} · {{i.classification}}</td><td>{{money(i.amount)}}</td><td>{{i.originMonth}} / {{i.settlementMonth}}</td></tr></tbody></table></div><RouterLink v-if="selected.originalBatchId" :to="base+'/payslips/'+selected.originalBatchId">{{x('查看原工资单','View original payslip')}}</RouterLink></article></section></template>
